1	package com.example.starter.forestry.service;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.time.YearMonth;
6	import java.util.List;
7	import java.util.UUID;
8	
9	import org.springframework.http.HttpStatus;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.PlatformTransactionManager;
12	import org.springframework.transaction.support.TransactionTemplate;
13	
14	import com.example.starter.forestry.domain.ApplicationStatus;
15	import com.example.starter.forestry.domain.HarvestType;
16	import com.example.starter.forestry.domain.IdempotentOperation;
17	import com.example.starter.forestry.domain.LicenseStatus;
18	import com.example.starter.forestry.domain.RenewalStatus;
19	import com.example.starter.forestry.dto.AcceptanceRequest;
20	import com.example.starter.forestry.dto.ApplicationView;
21	import com.example.starter.forestry.dto.ApplyRequest;
22	import com.example.starter.forestry.dto.ConfirmRequest;
23	import com.example.starter.forestry.dto.IssueRequest;
24	import com.example.starter.forestry.dto.LicenseView;
25	import com.example.starter.forestry.dto.RenewalView;
26	import com.example.starter.forestry.dto.ReviewRequest;
27	import com.example.starter.forestry.po.ApplicationPO;
28	import com.example.starter.forestry.po.IdempotentRecordPO;
29	import com.example.starter.forestry.po.LicensePO;
30	import com.example.starter.forestry.po.RenewalPO;
31	import com.example.starter.forestry.po.SubplotPO;
32	import com.example.starter.forestry.repo.ApplicationRepository;
33	import com.example.starter.forestry.repo.IdempotencyRepository;
34	import com.example.starter.forestry.repo.LateEventRepository;
35	import com.example.starter.forestry.repo.LicenseRepository;
36	import com.example.starter.forestry.repo.QuotaRepository;
37	import com.example.starter.forestry.repo.RenewalRepository;
38	import com.example.starter.forestry.repo.RestrictionRepository;
39	import com.example.starter.forestry.repo.SubplotRepository;
40	import com.example.starter.forestry.support.BusinessClock;
41	import com.example.starter.forestry.support.Fingerprints;
42	import com.example.starter.forestry.web.ApiException;
43	import com.fasterxml.jackson.databind.ObjectMapper;
44	
45	/**
46	 * 林木采伐许可与迹地更新联动服务。
47	 *
48	 * <p>关键口径（全部日期取 UTC 日界）：
49	 * <ul>
50	 *   <li>限额按树种+年度分档，发证时串行校验；恰达限额合法，超出整笔拒绝且不占用。</li>
51	 *   <li>生态公益林、禁伐区一律拒绝；主伐林龄须 ≥ 成熟龄，恰达合法。</li>
52	 *   <li>采伐期限 = 发证日 + 90 个自然日，第 90 日确认有效；逾期证件自动作废、限额当日释放。</li>
53	 *   <li>更新期限为采伐确认翌年 12 月 31 日；合格率 = 合格株数/总株数，≥ 0.85 合格，恰达合法。</li>
54	 *   <li>首次验收不合格给一次补植机会，补植期限 6 个月月末（含当日）；仍不合格列入限批名单 1 年。</li>
55	 *   <li>申请/发证/采伐确认/验收以 (operation, requestId) 幂等：指纹覆盖全部业务字段；
56	 *       同键同参返回首次结果，同键异参 409 且不产生任何业务副作用。</li>
57	 * </ul>
58	 */
59	@Service
60	public class ForestryService {
61	
62	    /** 采伐期限自然日数（含发证当日起第 90 日） */
63	    private static final int HARVEST_DAYS = 90;
64	    /** 验收合格线：qualified/total ≥ 0.85，以整数比较避免浮点误差 */
65	    private static final int PASS_RATE_PERCENT = 85;
66	    /** 补植仍不合格后的限批期限（年，含截止当日） */
67	    private static final int RESTRICTION_YEARS = 1;
68	    /** 并发同键请求等待首处理完成的最大毫秒数 */
69	    private static final long IDEMPOTENT_WAIT_MILLIS = 10_000L;
70	
71	    private final ApplicationRepository applicationRepository;
72	    private final SubplotRepository subplotRepository;
73	    private final QuotaRepository quotaRepository;
74	    private final LicenseRepository licenseRepository;
75	    private final RenewalRepository renewalRepository;
76	    private final RestrictionRepository restrictionRepository;
77	    private final IdempotencyRepository idempotencyRepository;
78	    private final LateEventRepository lateEventRepository;
79	    private final BusinessClock clock;
80	    private final ObjectMapper objectMapper;
81	    private final PlatformTransactionManager transactionManager;
82	
83	    public ForestryService(ApplicationRepository applicationRepository,
84	                           SubplotRepository subplotRepository,
85	                           QuotaRepository quotaRepository,
86	                           LicenseRepository licenseRepository,
87	                           RenewalRepository renewalRepository,
88	                           RestrictionRepository restrictionRepository,
89	                           IdempotencyRepository idempotencyRepository,
90	                           LateEventRepository lateEventRepository,
91	                           BusinessClock clock,
92	                           ObjectMapper objectMapper,
93	                           PlatformTransactionManager transactionManager) {
94	        this.applicationRepository = applicationRepository;
95	        this.subplotRepository = subplotRepository;
96	        this.quotaRepository = quotaRepository;
97	        this.licenseRepository = licenseRepository;
98	        this.renewalRepository = renewalRepository;
99	        this.restrictionRepository = restrictionRepository;
100	        this.idempotencyRepository = idempotencyRepository;
101	        this.lateEventRepository = lateEventRepository;
102	        this.clock = clock;
103	        this.objectMapper = objectMapper;
104	        this.transactionManager = transactionManager;
105	    }
106	
107	    // ------------------------------------------------------------------
108	    // 公开业务操作
109	    // ------------------------------------------------------------------
110	
111	    /**
112	     * 提交采伐申请。静态资格校验（限批/禁伐/公益林/成熟龄）在此完成；
113	     * 限额余额在发证时串行校验。
114	     */
115	    public ApplicationView apply(ApplyRequest request) {
116	        HarvestType harvestType = parseHarvestType(request.harvestType());
117	        String fingerprint = Fingerprints.sha256(String.join("|",
118	                request.requestId(), request.operatorId(), request.subplotId(), request.speciesCode(),
119	                request.harvestType(), request.volume().stripTrailingZeros().toPlainString()));
120	
121	        return withIdempotency(IdempotentOperation.APPLY, request.requestId(), fingerprint,
122	                "APPLICATION", ApplicationView.class, () -> doApply(request, harvestType));
123	    }
124	
125	    private ApplicationView doApply(ApplyRequest request, HarvestType harvestType) {
126	        LocalDate today = clock.today();
127	
128	        if (restrictionRepository.isRestricted(request.operatorId(), today)) {
129	            throw ApiException.badRequest("OPERATOR_RESTRICTED", "经营主体处于限批期内，新采伐申请一律拒绝");
130	        }
131	
132	        SubplotPO subplot = subplotRepository.findById(request.subplotId());
133	        if (subplot == null) {
134	            throw ApiException.notFound("SUBPLOT_NOT_FOUND", "小班不存在: " + request.subplotId());
135	        }
136	        if (!subplot.speciesCode().equals(request.speciesCode())) {
137	            throw ApiException.badRequest("SPECIES_MISMATCH",
138	                    "申请树种与小班树种不一致: " + subplot.speciesCode());
139	        }
140	        if (subplot.protectedZone()) {
141	            throw rejection("PROTECTED_ZONE_FORBIDDEN", "禁伐区小班禁止采伐: " + subplot.id());
142	        }
143	        if ("PUBLIC_WELFARE".equals(subplot.forestCategory())) {
144	            throw rejection("PUBLIC_WELFARE_FORBIDDEN", "生态公益林禁止商业性采伐: " + subplot.id());
145	        }
146	        if (harvestType == HarvestType.MAIN && subplot.standAge() < subplot.matureAge()) {
147	            throw rejection("STAND_AGE_NOT_MATURE",
148	                    "主伐林龄 " + subplot.standAge() + " 低于成熟龄 " + subplot.matureAge());
149	        }
150	        if (quotaRepository.findTotal(subplot.speciesCode(), today.getYear()) == null) {
151	            throw rejection("QUOTA_TIER_NOT_FOUND",
152	                    "年度限额档位不存在: " + subplot.speciesCode() + " / " + today.getYear());
153	        }
154	
155	        ApplicationPO po = new ApplicationPO(
156	                "APP-" + UUID.randomUUID(),
157	                request.requestId(),
158	                request.operatorId(),
159	                subplot.id(),
160	                subplot.speciesCode(),
161	                today.getYear(),
162	                harvestType.name(),
163	                request.volume(),
164	                ApplicationStatus.SUBMITTED.name(),
165	                null, null, false, today, null, null);
166	        applicationRepository.insert(po);
167	        return toApplicationView(po);
168	    }
169	
170	    /**
171	     * 审核：通过转 REVIEW_PASSED；不通过填拒绝原因转 REVIEW_REJECTED。
172	     */
173	    public ApplicationView review(String applicationId, ReviewRequest request) {
174	        return new TransactionTemplate(transactionManager).execute(status -> {
175	            ApplicationPO app = mustFindApplication(applicationId);
176	            if (app.archived()) {
177	                recordLateEvent(app.id(), app.licenseId(), "REVIEW",
178	                        "approved=" + request.approved());
179	                throw ApiException.conflict("APPLICATION_ARCHIVED", "申请已归档，迟到审核仅记录事件");
180	            }
181	            if (!ApplicationStatus.SUBMITTED.name().equals(app.status())) {
182	                throw ApiException.conflict("INVALID_STATUS",
183	                        "当前状态 " + app.status() + " 不允许审核");
184	            }
185	            LocalDate today = clock.today();
186	            if (Boolean.TRUE.equals(request.approved())) {
187	                applicationRepository.review(app.id(), ApplicationStatus.REVIEW_PASSED.name(), null, today);
188	            } else {
189	                if (request.comment() == null || request.comment().isBlank()) {
190	                    throw ApiException.badRequest("REJECT_REASON_REQUIRED", "审核拒绝必须填写拒绝原因");
191	                }
192	                applicationRepository.review(app.id(), ApplicationStatus.REVIEW_REJECTED.name(),
193	                        request.comment(), today);
194	            }
195	            return toApplicationView(applicationRepository.findById(app.id()));
196	        });
197	    }
198	
199	    /**
200	     * 发证：同一限额档位串行校验（行锁），同一小班同时刻只允许一张有效证。
201	     */
202	    public LicenseView issue(IssueRequest request) {
203	        String fingerprint = Fingerprints.sha256(request.requestId() + "|" + request.applicationId());
204	        return withIdempotency(IdempotentOperation.ISSUE, request.requestId(), fingerprint,
205	                "LICENSE", LicenseView.class, () -> doIssue(request));
206	    }
207	
208	    private LicenseView doIssue(IssueRequest request) {
209	        LocalDate today = clock.today();
210	        ApplicationPO app = mustFindApplication(request.applicationId());
211	        if (app.archived()) {
212	            recordLateEvent(app.id(), null, "ISSUE", request.applicationId());
213	            throw ApiException.conflict("APPLICATION_ARCHIVED", "申请已归档，迟到发证仅记录事件");
214	        }
215	        if (!ApplicationStatus.REVIEW_PASSED.name().equals(app.status())) {
216	            throw ApiException.conflict("INVALID_STATUS",
217	                    "当前状态 " + app.status() + " 不允许发证");
218	        }
219	        if (restrictionRepository.isRestricted(app.operatorId(), today)) {
220	            throw ApiException.badRequest("OPERATOR_RESTRICTED", "经营主体处于限批期内，禁止发证");
221	        }
222	
223	        // 锁定限额档位行：同树种同年度发证全局串行，杜绝并发合计超限
224	        BigDecimal total = quotaRepository.findTotalForUpdate(app.speciesCode(), app.quotaYear());
225	        if (total == null) {
226	            throw ApiException.badRequest("QUOTA_TIER_NOT_FOUND",
227	                    "年度限额档位不存在: " + app.speciesCode() + " / " + app.quotaYear());
228	        }
229	        BigDecimal held = quotaRepository.sumHeld(app.speciesCode(), app.quotaYear());
230	        if (held.add(app.volume()).compareTo(total) > 0) {
231	            throw ApiException.conflict("QUOTA_EXCEEDED",
232	                    "超出年度采伐限额：已占 " + held + " + 本笔 " + app.volume() + " > 限额 " + total);
233	        }
234	
235	        // 锁定小班行：同一小班同时刻只允许一张有效证
236	        subplotRepository.lockForUpdate(app.subplotId());
237	        if (applicationRepository.countActiveLicensesOnSubplot(app.subplotId()) > 0) {
238	            throw ApiException.conflict("SUBPLOT_LICENSE_ACTIVE", "该小班存在有效采伐证，禁止重复发证");
239	        }
240	
241	        LocalDate expireDate = today.plusDays(HARVEST_DAYS);
242	        LicensePO license = new LicensePO(
243	                "LIC-" + UUID.randomUUID(),
244	                app.id(), app.operatorId(), app.subplotId(), app.speciesCode(), app.quotaYear(),
245	                app.volume(), LicenseStatus.ISSUED.name(), today, expireDate, null, null);
246	        licenseRepository.insert(license);
247	        quotaRepository.appendLedger(app.speciesCode(), app.quotaYear(), app.id(), license.id(),
248	                app.volume(), "HOLD", today);
249	        applicationRepository.attachLicense(app.id(), license.id(), ApplicationStatus.LICENSED.name());
250	        return toLicenseView(license);
251	    }
252	
253	    /**
254	     * 采伐确认：第 90 日（含）内有效；逾期首次确认触发证件作废并在独立事务中释放限额。
255	     */
256	    public LicenseView confirm(ConfirmRequest request) {
257	        String fingerprint = Fingerprints.sha256(request.requestId() + "|" + request.licenseId());
258	        return withIdempotency(IdempotentOperation.CONFIRM, request.requestId(), fingerprint,
259	                "LICENSE", LicenseView.class, () -> doConfirm(request));
260	    }
261	
262	    private LicenseView doConfirm(ConfirmRequest request) {
263	        LocalDate today = clock.today();
264	        LicensePO license = mustFindLicense(request.licenseId());
265	        ApplicationPO app = mustFindApplication(license.applicationId());
266	        if (app.archived()) {
267	            recordLateEvent(app.id(), license.id(), "CONFIRM", request.licenseId());
268	            throw ApiException.conflict("APPLICATION_ARCHIVED", "申请已归档，迟到采伐确认仅记录事件");
269	        }
270	
271	        if (LicenseStatus.HARVESTED.name().equals(license.status())) {
272	            return toLicenseView(license);
273	        }
274	        if (LicenseStatus.VOID.name().equals(license.status())) {
275	            throw ApiException.conflict("LICENSE_VOID", "采伐证已逾期作废，采伐确认无效");
276	        }
277	
278	        if (today.isAfter(license.expireDate())) {
279	            // 逾期：条件作废 + 限额当日释放，独立事务先落库（随后主事务回滚不影响作废结果），
280	            // 再向调用方返回作废错误
281	            TransactionTemplate requiresNew = new TransactionTemplate(transactionManager);
282	            requiresNew.setPropagationBehavior(TransactionTemplate.PROPAGATION_REQUIRES_NEW);
283	            boolean voided = requiresNew.execute(status -> {
284	                LicensePO fresh = mustFindLicense(license.id());
285	                if (!LicenseStatus.ISSUED.name().equals(fresh.status())) {
286	                    return false;
287	                }
288	                int rows = licenseRepository.markVoidIfIssued(license.id(), today);
289	                if (rows == 0) {
290	                    return false;
291	                }
292	                applicationRepository.updateStatus(app.id(), ApplicationStatus.LICENSE_VOID.name());
293	                quotaRepository.appendLedger(license.speciesCode(), license.quotaYear(),
294	                        app.id(), license.id(), license.volume().negate(), "RELEASE", today);
295	                return true;
296	            });
297	            if (Boolean.TRUE.equals(voided)) {
298	                throw ApiException.conflict("LICENSE_EXPIRED",
299	                        "采伐证已逾 " + HARVEST_DAYS + " 日期限（截止 " + license.expireDate() + "），证件作废且限额已释放");
300	            }
301	            LicensePO reloaded = mustFindLicense(license.id());
302	            if (LicenseStatus.HARVESTED.name().equals(reloaded.status())) {
303	                return toLicenseView(reloaded);
304	            }
305	            throw ApiException.conflict("LICENSE_VOID", "采伐证已逾期作废，采伐确认无效");
306	        }
307	
308	        // 期限内：CAS 置 HARVESTED，与并发作废竞争形成唯一终态
309	        int rows = licenseRepository.markHarvestedIfIssued(license.id(), today);
310	        if (rows == 0) {
311	            LicensePO reloaded = mustFindLicense(license.id());
312	            if (LicenseStatus.HARVESTED.name().equals(reloaded.status())) {
313	                return toLicenseView(reloaded);
314	            }
315	            throw ApiException.conflict("LICENSE_VOID", "采伐证已作废，采伐确认无效");
316	        }
317	        applicationRepository.updateStatus(app.id(), ApplicationStatus.HARVESTED.name());
318	        RenewalPO renewal = new RenewalPO(
319	                "REN-" + UUID.randomUUID(),
320	                app.id(), app.operatorId(), RenewalStatus.PENDING.name(),
321	                LocalDate.of(today.getYear() + 1, 12, 31),
322	                null, null, null, null, today);
323	        renewalRepository.insert(renewal);
324	        return toLicenseView(mustFindLicense(license.id()));
325	    }
326	
327	    /**
328	     * 更新验收提交：首次不合格进入补植（提交本身作为首次结果提交并缓存），
329	     * 补植验收仍不合格则列入限批名单。
330	     */
331	    public RenewalView acceptance(AcceptanceRequest request) {
332	        if (request.qualifiedCount() > request.totalCount()) {
333	            throw ApiException.badRequest("INVALID_COUNTS", "合格株数不得大于总株数");
334	        }
335	        String fingerprint = Fingerprints.sha256(String.join("|",
336	                request.requestId(), request.applicationId(),
337	                request.qualifiedCount().toString(), request.totalCount().toString()));
338	        return withIdempotency(IdempotentOperation.ACCEPTANCE, request.requestId(), fingerprint,
339	                "RENEWAL", RenewalView.class, () -> doAcceptance(request));
340	    }
341	
342	    private RenewalView doAcceptance(AcceptanceRequest request) {
343	        LocalDate today = clock.today();
344	        ApplicationPO app = mustFindApplication(request.applicationId());
345	        if (app.archived()) {
346	            recordLateEvent(app.id(), app.licenseId(), "ACCEPTANCE",
347	                    request.qualifiedCount() + "/" + request.totalCount());
348	            throw ApiException.conflict("APPLICATION_ARCHIVED", "申请已归档，迟到验收仅记录事件");
349	        }
350	        RenewalPO renewal = renewalRepository.findByApplicationId(app.id());
351	        if (renewal == null) {
352	            throw ApiException.conflict("NO_RENEWAL_OBLIGATION", "该申请尚未采伐确认，无更新义务");
353	        }
354	
355	        // 合格判定：qualified/total ≥ 85%（长整数比较，恰达合法）
356	        boolean qualified = request.qualifiedCount().longValue() * 100
357	                >= request.totalCount().longValue() * PASS_RATE_PERCENT;
358	        BigDecimal rate = BigDecimal.valueOf(request.qualifiedCount())
359	                .divide(BigDecimal.valueOf(request.totalCount()), 4, java.math.RoundingMode.HALF_UP);
360	
361	        switch (RenewalStatus.valueOf(renewal.status())) {
362	            case PENDING -> {
363	                if (today.isAfter(renewal.deadline())) {
364	                    throw ApiException.badRequest("RENEWAL_DEADLINE_PASSED",
365	                            "已超过首次更新期限 " + renewal.deadline());
366	                }
367	                if (qualified) {
368	                    int rows = renewalRepository.markPassedFromPending(app.id(), rate, today);
369	                    if (rows == 0) {
370	                        throw ApiException.conflict("RENEWAL_STATE_CHANGED", "更新状态已被并发改变，请重试");
371	                    }
372	                    applicationRepository.updateStatus(app.id(), ApplicationStatus.RENEWAL_DONE.name());
373	                } else {
374	                    // 首次不合格：给予一次补植机会，期限 6 个月月末（含当日）
375	                    LocalDate plusSix = today.plusMonths(6);
376	                    LocalDate replantDeadline = YearMonth.from(plusSix).atEndOfMonth();
377	                    renewalRepository.markReplanting(app.id(), rate, today, replantDeadline);
378	                }
379	                return toRenewalView(renewalRepository.findByApplicationId(app.id()));
380	            }
381	            case REPLANTING -> {
382	                if (renewal.replantDeadline() != null && today.isAfter(renewal.replantDeadline())) {
383	                    throw ApiException.badRequest("REPLANT_DEADLINE_PASSED",
384	                            "已超过补植期限 " + renewal.replantDeadline());
385	                }
386	                String target = qualified ? RenewalStatus.PASSED.name() : RenewalStatus.FAILED.name();
387	                int rows = renewalRepository.completeReplant(app.id(), target, rate, today);
388	                if (rows == 0) {
389	                    throw ApiException.conflict("RENEWAL_STATE_CHANGED", "更新状态已被并发改变，请重试");
390	                }
391	                if (qualified) {
392	                    applicationRepository.updateStatus(app.id(), ApplicationStatus.RENEWAL_DONE.name());
393	                } else {
394	                    // 补植仍不合格：经营主体列入限批名单，期限 1 年（含截止当日）
395	                    applicationRepository.updateStatus(app.id(), ApplicationStatus.RENEWAL_FAILED.name());
396	                    restrictionRepository.add(app.operatorId(),
397	                            "迹地更新补植验收仍不合格，合格率 " + rate,
398	                            today, today.plusYears(RESTRICTION_YEARS));
399	                }
400	                return toRenewalView(renewalRepository.findByApplicationId(app.id()));
401	            }
402	            case PASSED, FAILED -> throw ApiException.conflict("RENEWAL_TERMINAL",
403	                    "更新义务已终态（" + renewal.status() + "），不能重复验收");
404	        }
405	        throw ApiException.badRequest("INVALID_RENEWAL_STATE", "未知更新状态: " + renewal.status());
406	    }
407	
408	    /**
409	     * 归档（终态）：重复归档幂等成功；归档后迟到数据只记录迟到事件。
410	     */
411	    public ApplicationView archive(String applicationId) {
412	        return new TransactionTemplate(transactionManager).execute(status -> {
413	            ApplicationPO app = mustFindApplication(applicationId);
414	            if (app.archived()) {
415	                return toApplicationView(app);
416	            }
417	            applicationRepository.archive(app.id(), clock.today());
418	            return toApplicationView(applicationRepository.findById(app.id()));
419	        });
420	    }
421	
422	    /**
423	     * 扫描并处理所有已逾期（expire_date &lt; 今天 UTC）仍有效的证件：
424	     * 条件作废 + 限额当日释放。与 confirm 的 CAS 共同保证唯一终态。
425	     *
426	     * @return 本次新作废证件数量
427	     */
428	    public int processExpiredLicenses() {
429	        return new TransactionTemplate(transactionManager).execute(status -> {
430	            LocalDate today = clock.today();
431	            List<LicensePO> expired = licenseRepository.findIssuedExpiredForUpdate(today);
432	            int count = 0;
433	            for (LicensePO license : expired) {
434	                int rows = licenseRepository.markVoidIfIssued(license.id(), today);
435	                if (rows == 0) {
436	                    continue;
437	                }
438	                applicationRepository.updateStatus(license.applicationId(),
439	                        ApplicationStatus.LICENSE_VOID.name());
440	                quotaRepository.appendLedger(license.speciesCode(), license.quotaYear(),
441	                        license.applicationId(), license.id(),
442	                        license.volume().negate(), "RELEASE", today);
443	                count++;
444	            }
445	            return count;
446	        });
447	    }
448	
449	    // ------------------------------------------------------------------
450	    // 查询
451	    // ------------------------------------------------------------------
452	
453	    public ApplicationView getApplication(String applicationId) {
454	        return toApplicationView(mustFindApplication(applicationId));
455	    }
456	
457	    public LicenseView getLicense(String licenseId) {
458	        return toLicenseView(mustFindLicense(licenseId));
459	    }
460	
461	    public RenewalView getRenewal(String applicationId) {
462	        RenewalPO renewal = renewalRepository.findByApplicationId(applicationId);
463	        if (renewal == null) {
464	            throw ApiException.notFound("RENEWAL_NOT_FOUND", "更新义务不存在: " + applicationId);
465	        }
466	        return toRenewalView(renewal);
467	    }
468	
469	    // ------------------------------------------------------------------
470	    // 幂等封装
471	    // ------------------------------------------------------------------
472	
473	    /**
474	     * 业务操作的幂等包装。
475	     * <p>首处理者插入 PENDING 占位并在同一事务内执行业务；同键同参的并发请求等待 DONE
476	     * 后重放首次结果（成功返回首次响应，业务拒绝重放首次拒绝）；同键异参立即 409，
477	     * 不触碰任何业务数据、不占用限额。业务异常（如 422/409 规则拒绝）同样固化为首次
478	     * 结果并提交；非业务异常回滚，不缓存。
479	     */
480	    private <T> T withIdempotency(IdempotentOperation operation, String requestId, String fingerprint,
481	                                  String responseType, Class<T> responseClass, SupplierTx<T> action) {
482	        TransactionTemplate template = new TransactionTemplate(transactionManager);
483	        @SuppressWarnings("unchecked")
484	        java.util.concurrent.atomic.AtomicReference<ApiException> pendingError =
485	                new java.util.concurrent.atomic.AtomicReference<>();
486	        boolean[] acquired = {false};
487	        T result = template.execute(status -> {
488	            boolean inserted = idempotencyRepository.tryInsertPending(operation, requestId,
489	                    fingerprint, clock.today());
490	            if (!inserted) {
491	                return null;
492	            }
493	            acquired[0] = true;
494	            try {
495	                T value = action.get();
496	                idempotencyRepository.markDone(operation, requestId, responseType, null,
497	                        extractRefId(value), writeJson(value));
498	                return value;
499	            } catch (ApiException e) {
500	                // 业务拒绝也是确定性“首次结果”：固化后随事务提交，随后在事务外重放
501	                idempotencyRepository.markDone(operation, requestId, "ERROR",
502	                        e.getStatus().value(), null,
503	                        writeJson(new com.example.starter.forestry.web.ErrorResponse(
504	                                e.getErrorCode(), e.getMessage())));
505	                pendingError.set(e);
506	                return null;
507	            }
508	        });
509	        if (acquired[0]) {
510	            if (pendingError.get() != null) {
511	                throw pendingError.get();
512	            }
513	            return result;
514	        }
515	
516	        // 同键已存在：指纹不符立即 409（无论对方处理中还是已完成，均不产生副作用）
517	        IdempotentRecordPO existing = idempotencyRepository.find(operation, requestId);
518	        if (existing == null) {
519	            throw ApiException.conflict("IDEMPOTENCY_RACE", "幂等记录状态异常，请重试");
520	        }
521	        if (!existing.fingerprint().equals(fingerprint)) {
522	            throw new ApiException(HttpStatus.CONFLICT, "IDEMPOTENCY_CONFLICT",
523	                    "requestId=" + requestId + " 已用于不同业务参数的请求");
524	        }
525	
526	        // 同键同参：等待首处理者完成后重放首次结果
527	        long deadline = System.currentTimeMillis() + IDEMPOTENT_WAIT_MILLIS;
528	        IdempotentRecordPO done = existing;
529	        while ("PENDING".equals(done.status()) && System.currentTimeMillis() < deadline) {
530	            try {
531	                Thread.sleep(50);
532	            } catch (InterruptedException e) {
533	                Thread.currentThread().interrupt();
534	                throw ApiException.conflict("IDEMPOTENCY_WAIT_INTERRUPTED", "等待首次处理完成时被中断");
535	            }
536	            done = idempotencyRepository.find(operation, requestId);
537	            if (done == null) {
538	                throw ApiException.conflict("IDEMPOTENCY_RACE", "幂等记录状态异常，请重试");
539	            }
540	        }
541	        if ("PENDING".equals(done.status())) {
542	            throw new ApiException(HttpStatus.CONFLICT, "IDEMPOTENCY_PENDING",
543	                    "同一 requestId 的首次请求仍在处理中");
544	        }
545	        if ("ERROR".equals(done.responseType())) {
546	            com.example.starter.forestry.web.ErrorResponse error =
547	                    readJson(done.responseJson(), com.example.starter.forestry.web.ErrorResponse.class);
548	            throw new ApiException(HttpStatus.valueOf(done.responseStatus()), error.errorCode(), error.message());
549	        }
550	        return readJson(done.responseJson(), responseClass);
551	    }
552	
553	    private String extractRefId(Object view) {
554	        if (view instanceof ApplicationView a) {
555	            return a.id();
556	        }
557	        if (view instanceof LicenseView l) {
558	            return l.id();
559	        }
560	        if (view instanceof RenewalView r) {
561	            return r.id();
562	        }
563	        return null;
564	    }
565	
566	    private String writeJson(Object value) {
567	        try {
568	            return objectMapper.writeValueAsString(value);
569	        } catch (Exception e) {
570	            throw new IllegalStateException("序列化首次响应失败", e);
571	        }
572	    }
573	
574	    private <T> T readJson(String json, Class<T> type) {
575	        try {
576	            return objectMapper.readValue(json, type);
577	        } catch (Exception e) {
578	            throw new IllegalStateException("解析首次响应快照失败", e);
579	        }
580	    }
581	
582	    // ------------------------------------------------------------------
583	    // 辅助方法
584	    // ------------------------------------------------------------------
585	
586	    private HarvestType parseHarvestType(String raw) {
587	        try {
588	            return HarvestType.valueOf(raw);
589	        } catch (IllegalArgumentException e) {
590	            throw ApiException.badRequest("INVALID_HARVEST_TYPE",
591	                    "未知采伐类型: " + raw + "（支持 MAIN/TENDING/REFORMATION）");
592	        }
593	    }
594	
595	    private ApiException rejection(String code, String message) {
596	        // 资格类拒绝返回 422：请求格式正确但业务规则拒绝
597	        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
598	    }
599	
600	    /**
601	     * 记录归档后迟到事件：使用独立事务提交，确保外层业务事务随后回滚时事件仍保留。
602	     */
603	    private void recordLateEvent(String applicationId, String licenseId, String eventType, String payload) {
604	        TransactionTemplate requiresNew = new TransactionTemplate(transactionManager);
605	        requiresNew.setPropagationBehavior(TransactionTemplate.PROPAGATION_REQUIRES_NEW);
606	        requiresNew.execute(status -> {
607	            lateEventRepository.record(applicationId, licenseId, eventType, payload, clock.today());
608	            return null;
609	        });
610	    }
611	
612	    private ApplicationPO mustFindApplication(String id) {
613	        ApplicationPO app = applicationRepository.findById(id);
614	        if (app == null) {
615	            throw ApiException.notFound("APPLICATION_NOT_FOUND", "采伐申请不存在: " + id);
616	        }
617	        return app;
618	    }
619	
620	    private LicensePO mustFindLicense(String id) {
621	        LicensePO license = licenseRepository.findById(id);
622	        if (license == null) {
623	            throw ApiException.notFound("LICENSE_NOT_FOUND", "采伐许可证不存在: " + id);
624	        }
625	        return license;
626	    }
627	
628	    private ApplicationView toApplicationView(ApplicationPO po) {
629	        return new ApplicationView(
630	                po.id(), po.status(), po.operatorId(), po.subplotId(), po.speciesCode(),
631	                po.quotaYear(), po.harvestType(), po.volume(), po.licenseId(),
632	                po.rejectReason(), po.createdDate(), po.archivedDate());
633	    }
634	
635	    private LicenseView toLicenseView(LicensePO po) {
636	        return new LicenseView(
637	                po.id(), po.applicationId(), po.operatorId(), po.subplotId(), po.speciesCode(),
638	                po.quotaYear(), po.status(), po.issueDate(), po.expireDate(), po.harvestDate());
639	    }
640	
641	    private RenewalView toRenewalView(RenewalPO po) {
642	        return new RenewalView(
643	                po.id(), po.applicationId(), po.operatorId(), po.status(), po.deadline(),
644	                po.replantDeadline(), po.qualifiedRate(), po.acceptedDate(), po.replantAcceptedDate());
645	    }
646	
647	    /** 可在事务模板内抛受检包装的业务供应商。 */
648	    @FunctionalInterface
649	    private interface SupplierTx<T> {
650	        T get();
651	    }
652	}
