20	 * 合成数据：杉木 CUNNINGHAMIA 2026 年限额 50 立方米；可用成熟小班 SP-002、SP-006。
21	 */
22	class QuotaBoundaryTest extends AbstractForestryTest {
23	
24	    private LicenseView prepare(String prefix, String subplotId, String volume) {
25	        var app = service.apply(new ApplyRequest(prefix + "-apply", "OP-Q", subplotId,
26	                "CUNNINGHAMIA", "MAIN", new BigDecimal(volume)));
27	        service.review(app.id(), new ReviewRequest(true, "OK"));
28	        return service.issue(new IssueRequest(prefix + "-issue", app.id()));
29	    }
30	
31	    @Test
32	    void exactlyReachingQuotaIsLegal() {
33	        LicenseView first = prepare("q-exact-1", "SP-002", "30.00");
34	        LicenseView second = prepare("q-exact-2", "SP-006", "20.00");
35	
36	        assertThat(first.status()).isEqualTo("ISSUED");
37	        assertThat(second.status()).isEqualTo("ISSUED");
38	
39	        BigDecimal held = jdbc.queryForObject(
40	                "SELECT COALESCE(SUM(volume),0) FROM quota_ledger WHERE species_code='CUNNINGHAMIA' AND quota_year=2026",
41	                BigDecimal.class);
42	        assertThat(held).isEqualByComparingTo("50.00");
43	    }
44	
45	    @Test
46	    void exceedingQuotaRejectsWholeApplicationAndOccupiesNothing() {
47	        prepare("q-over-1", "SP-002", "30.00");
48	
49	        var app = service.apply(new ApplyRequest("q-over-2-apply", "OP-Q", "SP-006",
50	                "CUNNINGHAMIA", "MAIN", new BigDecimal("20.01")));
51	        service.review(app.id(), new ReviewRequest(true, "OK"));
52	
53	        assertThatThrownBy(() -> service.issue(new IssueRequest("q-over-2-issue", app.id())))
54	                .isInstanceOfSatisfying(ApiException.class, ex -> {
55	                    assertThat(ex.getStatus()).isEqualTo(HttpStatus.CONFLICT);
56	                    assertThat(ex.getErrorCode()).isEqualTo("QUOTA_EXCEEDED");
57	                });
58	
59	        // 超限额整笔拒绝：台账仍为 30，未产生采伐证
60	        BigDecimal held = jdbc.queryForObject(
61	                "SELECT COALESCE(SUM(volume),0) FROM quota_ledger WHERE species_code='CUNNINGHAMIA' AND quota_year=2026",
62	                BigDecimal.class);
63	        assertThat(held).isEqualByComparingTo("30.00");
64	        Integer licenses = jdbc.queryForObject(
65	                "SELECT COUNT(*) FROM harvest_license WHERE application_id=?", Integer.class, app.id());
66	        assertThat(licenses).isZero();
67	    }
68	
69	    @Test
70	    void quotaReleasedOnExpiryCanBeReused() {
71	        LicenseView license = prepare("q-rel-1", "SP-002", "50.00");
72	
73	        // 逾期扫描：证件作废，限额当日（2026-05-31）释放
74	        clock.setToday(LocalDate.of(2026, 5, 31));
75	        int voided = service.processExpiredLicenses();
76	        assertThat(voided).isEqualTo(1);
77	
78	        BigDecimal held = jdbc.queryForObject(
79	                "SELECT COALESCE(SUM(volume),0) FROM quota_ledger WHERE species_code='CUNNINGHAMIA' AND quota_year=2026",
80	                BigDecimal.class);
81	        assertThat(held).isEqualByComparingTo("0.00");
82	
83	        // 释放后同档位新申请可再次占用全部 50
84	        clock.setToday(LocalDate.of(2026, 6, 1));
85	        LicenseView second = prepare("q-rel-2", "SP-006", "50.00");
86	        assertThat(second.status()).isEqualTo("ISSUED");
87	        assertThat(second.id()).isNotEqualTo(license.id());
88	    }
89	}
