60	    private HttpEntity<String> json(String rawJson) {
61	        org.springframework.http.HttpHeaders headers = new org.springframework.http.HttpHeaders();
62	        headers.setContentType(org.springframework.http.MediaType.APPLICATION_JSON);
63	        return new HttpEntity<>(rawJson, headers);
64	    }
65	
66	    private JsonNode body(ResponseEntity<String> response) throws Exception {
67	        return mapper.readTree(response.getBody());
68	    }
69	
70	    @Test
71	    void fullFlowOverHttp() throws Exception {
72	        // 1. 申请
73	        var applyReq = """
74	                {"requestId":"web-apply","operatorId":"OP-W","subplotId":"SP-001",
75	                 "speciesCode":"PINUS_MASSONIANA","harvestType":"MAIN","volume":20.00}
76	                """;
77	        ResponseEntity<String> created = rest.postForEntity(url("/api/applications"),
78	                json(applyReq), String.class);
79	        assertThat(created.getStatusCode()).isEqualTo(HttpStatus.CREATED);
80	        JsonNode app = body(created);
81	        assertThat(app.get("status").asText()).isEqualTo("SUBMITTED");
82	        String appId = app.get("id").asText();
83	
84	        // 2. 审核通过
85	        var reviewReq = """
86	                {"approved":true,"comment":"材料齐全"}
87	                """;
88	        ResponseEntity<String> reviewed = rest.postForEntity(
89	                url("/api/applications/" + appId + "/review"),
90	                json(reviewReq), String.class);
91	        assertThat(reviewed.getStatusCode()).isEqualTo(HttpStatus.OK);
92	        assertThat(body(reviewed).get("status").asText()).isEqualTo("REVIEW_PASSED");
93	
94	        // 3. 发证
95	        var issueReq = """
96	                {"requestId":"web-issue","applicationId":"%s"}
97	                """.formatted(appId);
98	        ResponseEntity<String> licensed = rest.postForEntity(url("/api/licenses"),
99	                json(issueReq), String.class);
100	        assertThat(licensed.getStatusCode()).isEqualTo(HttpStatus.CREATED);
101	        JsonNode license = body(licensed);
102	        assertThat(license.get("status").asText()).isEqualTo("ISSUED");
103	        assertThat(license.get("expireDate").asText()).isEqualTo("2026-05-30");
104	        String licenseId = license.get("id").asText();
105	
106	        // 4. 采伐确认（恰第 90 日）
107	        clock.setToday(LocalDate.of(2026, 5, 30));
108	        var confirmReq = """
109	                {"requestId":"web-confirm","licenseId":"%s"}
110	                """.formatted(licenseId);
111	        ResponseEntity<String> confirmed = rest.postForEntity(url("/api/licenses/confirm"),
112	                json(confirmReq), String.class);
113	        assertThat(confirmed.getStatusCode()).isEqualTo(HttpStatus.OK);
114	        assertThat(body(confirmed).get("status").asText()).isEqualTo("HARVESTED");
115	
116	        // 5. 更新验收（合格率恰达 0.85）
117	        clock.setToday(LocalDate.of(2027, 3, 1));
118	        var accReq = """
119	                {"requestId":"web-acc","applicationId":"%s","qualifiedCount":85,"totalCount":100}
120	                """.formatted(appId);
121	        ResponseEntity<String> accepted = rest.postForEntity(url("/api/renewals/acceptance"),
122	                json(accReq), String.class);
123	        assertThat(accepted.getStatusCode()).isEqualTo(HttpStatus.OK);
124	        assertThat(body(accepted).get("status").asText()).isEqualTo("PASSED");
125	        assertThat(new BigDecimal(body(accepted).get("qualifiedRate").asText()))
126	                .isEqualByComparingTo("0.8500");
127	
128	        // 6. 归档
129	        ResponseEntity<String> archived = rest.postForEntity(
130	                url("/api/applications/" + appId + "/archive"), null, String.class);
