package com.example.starter.forestry.domain;

/**
 * 采伐申请单状态机：
 * SUBMITTED（已申请）-> REVIEW_PASSED（审核通过）/ REVIEW_REJECTED（审核拒绝）
 * REVIEW_PASSED -> LICENSED（已发证）-> HARVESTED（采伐确认）
 * HARVESTED -> RENEWAL_DONE（更新验收通过）
 * 任一业务终态后可 ARCHIVED（归档，终态）。
 */
public enum ApplicationStatus {
    SUBMITTED,
    /** 蓄积设计值与合成蓄积表复核口径不一致，不予受理；允许一次补正 */
    CORRECTION_REQUIRED,
    /** 补正后设计值仍不一致，按撤回处理，不生成证照 */
    WITHDRAWN,
    REVIEW_PASSED,
    REVIEW_REJECTED,
    LICENSED,
    HARVESTED,
    RENEWAL_DONE,
    /** 限批联动：补植仍不合格，申请失败关闭 */
    RENEWAL_FAILED,
    /** 采伐证逾期作废，申请随证件关闭 */
    LICENSE_VOID,
    ARCHIVED
}

package com.example.starter.forestry.domain;

/**
 * 幂等操作类型。申请、设计值补正、发证、采伐确认与验收提交均以 requestId 幂等。
 */
public enum IdempotentOperation {
    APPLY,
    CORRECTION,
    ISSUE,
    CONFIRM,
    ACCEPTANCE
}

package com.example.starter.forestry.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 采伐申请提交请求。
 *
 * @param requestId      幂等键
 * @param operatorId     经营主体 ID
 * @param subplotId      小班 ID
 * @param speciesCode    树种编码（同时决定年度限额档位）
 * @param harvestType    采伐类型：MAIN 主伐 / TENDING 抚育 / REFORMATION 改造
 * @param treeCount      申请采伐株数，单位株
 * @param designedVolume 小班蓄积设计值，单位立方米；系统按合成蓄积表复核，
 *                       与复核口径（株数 × 单株蓄积）不一致不予受理
 */
public record ApplyRequest(
        @NotBlank String requestId,
        @NotBlank String operatorId,
        @NotBlank String subplotId,
        @NotBlank String speciesCode,
        @NotBlank String harvestType,
        @NotNull @Positive Integer treeCount,
        @NotNull @Positive BigDecimal designedVolume
) {
}

package com.example.starter.forestry.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 蓄积设计值补正请求（以 requestId 幂等）。仅 CORRECTION_REQUIRED 状态的申请可补正一次；
 * 补正后按合成蓄积表再复核，仍不一致按撤回处理，不生成证照。
 *
 * @param requestId      幂等键
 * @param treeCount      补正后的申请采伐株数，单位株
 * @param designedVolume 补正后的小班蓄积设计值，单位立方米
 */
public record CorrectionRequest(
        @NotBlank String requestId,
        @NotNull @Positive Integer treeCount,
        @NotNull @Positive BigDecimal designedVolume
) {
}

